const products=[{id:'curls',name:'The Deep Curl',cat:'Bundles',texture:'Deep curly',img:'curls-editorial.webp',images:['curls-editorial.webp','curls-angle.webp','curls-detail.webp','bundles-original.webp'],price:48000,tag:'Signature texture',desc:'Long, defined curls with a full silhouette.'},{id:'wave',name:'The Soft Wave',cat:'Wigs',texture:'Body wave',img:'wave-natural-v2.webp',images:['wave-natural-v2.webp','wave-editorial.webp','wave-angle.webp','wave-detail.webp'],price:125000,tag:'The everyday muse',desc:'An effortless wave with a soft silhouette. A centre part for everyday wear.'},{id:'blonde',name:'The Platinum Muse',cat:'Wigs',texture:'Straight',img:'blonde-editorial.webp',images:['blonde-editorial.webp','blonde-angle.webp','blonde-detail.webp'],price:155000,tag:'A little bold',desc:'Platinum-blonde lengths with a sleek centre part.'},{id:'volume',name:'The Full Bloom',cat:'Wigs',texture:'Coily',img:'volume-editorial.webp',images:['volume-editorial.webp','volume-angle.webp','volume-detail.webp'],price:110000,tag:'Volume, redefined',desc:'A full, rounded shape with closely defined coils.'},{id:'bundles',name:'The Curl Trio',cat:'Bundles',texture:'Deep curly',img:'bundles-original.webp',images:['bundles-original.webp','curls-detail.webp','curls-angle.webp'],price:45000,tag:'Build your bundle',desc:'Defined curls in a flexible bundle format. Choose the length and fullness you love.'},{id:'care',name:'The Care Ritual',cat:'Haircare',texture:'Care essentials',img:'care-branded-v2.webp',images:['care-branded-v2.webp'],price:24000,tag:'Love your lengths',desc:'A simple care concept for wash days, detangling and everything in between.'}];
