const articles=[{title:'Your curls, only softer.',category:'THE CURL GUIDE',img:'curls-editorial.webp',intro:'A little patience and a gentle routine go a long way.',sections:[['Start at the ends','Detangle in small sections, starting at the ends and gradually working upward. Use your fingers or a wide-tooth comb.'],['Make wash day gentle','Follow the product supplier’s care guidance. Avoid vigorous rubbing and rinse carefully, then blot with a towel.'],['Keep the shape','Allow curls to air dry where suitable. Store your hair carefully and protect it from friction overnight.']]},{title:'Find your first wig.',category:'THE BEGINNER EDIT',img:'blonde-editorial.webp',intro:'Think about how you want to feel, and how much styling time you have.',sections:[['Choose your silhouette','A sleek shape feels polished; curls bring volume; soft waves give you movement. Save a few looks before choosing.'],['Think beyond length','Check cap size, closure type, density and care instructions before purchasing. A good fit matters as much as a beautiful texture.'],['Ask before you commit','Confirm the colour, actual measurements and return policy with your seller. This concept store uses illustrative products.']]},{title:'A better wash-day ritual.',category:'CARE & KEEP',img:'care-branded-v2.webp',intro:'Create a routine that works with your hair, your schedule and your product instructions.',sections:[['Keep it simple','Choose a gentle cleansing routine recommended by your supplier. A small, consistent routine is easier to maintain.'],['Handle with care','Avoid pulling on the wefts or lace. Pat dry, detangle gently and keep direct heat to a minimum.'],['Store thoughtfully','Let hair dry fully before storage. Keep wigs on a stand where practical and bundles in a clean, dry place.']]}];
const money=n=>'₦'+Math.round(n).toLocaleString('en-NG');
function read(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}}
let saved=read('manemuse-saved',[]),bag=read('manemuse-bag',[]),filter='All',query='',sort='featured',selectedLength=18,bundleCount=1,photoIndex=0,quizStep=0,quizAnswers=[];
const app=document.querySelector('#app');
function persist(){try{localStorage.setItem('manemuse-saved',JSON.stringify(saved));localStorage.setItem('manemuse-bag',JSON.stringify(bag))}catch{} document.querySelector('#count').textContent=bag.reduce((n,x)=>n+x.qty,0)}
function toast(t){const e=document.querySelector('.toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2600)}
function card(p){return `<article class="product-card"><div class="product-image"><a href="#product/${p.id}" aria-label="View ${p.name}"><img src="assets/${p.img}" width="1086" height="1448" alt="${p.texture} hair style" loading="lazy"></a><button class="heart ${saved.includes(p.id)?'active':''}" data-action="save" data-id="${p.id}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${saved.includes(p.id)}">${icon('heart')}</button></div><div class="product-info"><small>${p.cat} / ${p.texture}</small><h3><a href="#product/${p.id}">${p.name}</a></h3><div class="price">${money(p.price)} <span>${p.cat==='Haircare'?'Care set':'From · '+(p.lengths?.[0]||16)+' inches'}</span></div></div></article>`}
function journalCards(){return articles.map((a,i)=>`<article class="journal-card"><a href="#article/${i}"><img class="journal-image" src="assets/${a.img}" alt="${a.category.toLowerCase()}" loading="lazy"></a><div><div class="eyebrow">${a.category}</div><h3><a href="#article/${i}">${a.title}</a></h3><a class="btn btn-outline-secondary text-link" href="#article/${i}">Read the edit </a></div></article>`).join('')}
function textureEdit(){return `<section class="section photo-edit"><div class="section-head"><div><span class="eyebrow">THE FINER DETAILS</span><h2>Texture, up close.</h2><p class="section-intro">See the detail. Find the texture that feels like you.</p></div><a class="btn btn-dark primary" href="#guide">${icon('guide')}<span>Find my texture</span></a></div><div class="grid texture-grid">${products.filter(p=>['curls','wave','blonde','volume'].includes(p.id)).map(p=>`<article class="editorial-card"><a class="editorial-photo" href="#product/${p.id}" aria-label="Explore ${p.texture}"><img src="assets/${p.id}-detail.webp" width="1086" height="1448" loading="lazy" alt="Close-up of ${p.texture.toLowerCase()} hair strands on ivory linen"></a><div class="editorial-info"><h3>${p.texture}</h3><a class="btn btn-outline-secondary" href="#product/${p.id}">Explore texture</a></div></article>`).join('')}</div></section>`}
const photoLabel=(p,i)=>{const f=p.images[i];return f.includes('natural-v2')?'Daylight portrait':f.includes('-back')?'Back view':f.includes('-angle')?'Side portrait':f.includes('-detail')?(p.cat==='Haircare'?'Care essentials':'Texture close-up'):p.cat==='Haircare'?'Care collection':f.includes('bundles-')?'Bundle set':'Front portrait'};
function museCarousel(){
 const photos=[['wave','wave-natural-v2.webp'],['curls','curls-angle.webp'],['blonde','blonde-angle.webp'],['volume','volume-angle.webp'],['bob','bob-editorial.webp'],['copper','copper-editorial.webp'],['wave','wave-angle.webp'],['curls','curls-editorial.webp'],['blonde','blonde-editorial.webp'],['volume','volume-editorial.webp']];
 const slides=duplicate=>photos.map(([id,file],i)=>{const p=products.find(x=>x.id===id);return `<article class="muse-slide" ${duplicate?'aria-hidden="true"':''}><a href="#product/${id}" ${duplicate?'tabindex="-1"':''} aria-label="View ${p.name}"><img src="assets/${file}" alt="${p.texture} hairstyle — ${p.name}" width="1086" height="1448" loading="lazy"><div class="muse-caption"><span>${p.texture}</span><h3>${p.name}</h3><span class="muse-view">View style</span></div></a></article>`}).join('');
 return `<section class="muse-carousel section" aria-label="ManeMuse style gallery" aria-roledescription="carousel"><div class="wrap section-head"><div><span class="eyebrow">THE STYLE GALLERY</span><h2>More ways to be you.</h2><p class="section-intro">Ten portraits. Find your next muse.</p></div><div class="carousel-controls"><button class="btn btn-outline-secondary" data-carousel="previous" aria-label="Previous photos">Previous</button><button class="btn btn-dark" data-carousel="pause" aria-pressed="false">Pause</button><button class="btn btn-outline-secondary" data-carousel="next" aria-label="Next photos">Next</button></div></div><div class="muse-viewport" tabindex="0" aria-label="Style photos. Swipe or use the arrow keys to browse."><div class="muse-track"><div class="muse-group">${slides(false)}</div><div class="muse-group muse-duplicates" aria-hidden="true">${slides(true)}</div></div></div></section>`;
}
let stopCarousel=()=>{};
function startCarousel(){
 stopCarousel();const root=document.querySelector('.muse-carousel');if(!root)return;
 const viewport=root.querySelector('.muse-viewport'),group=root.querySelector('.muse-group'),pause=root.querySelector('[data-carousel="pause"]');
 const controller=new AbortController(),opts={signal:controller.signal},motion=matchMedia('(prefers-reduced-motion: reduce)');let paused=motion.matches,hover=false,focused=false,visible=true,frame=0,last=0,position=0;
 const update=()=>{pause.textContent=paused?'Play':'Pause';pause.setAttribute('aria-pressed',String(paused));pause.setAttribute('aria-label',paused?'Play automatic photo scrolling':'Pause automatic photo scrolling');};update();
 const halt=()=>{paused=true;update();};
 const tick=time=>{const delta=Math.min(time-last,40);last=time;if(!paused&&!hover&&!focused&&visible&&!document.hidden){const distance=group.getBoundingClientRect().width+24;position+=delta*.035;if(position>=distance)position-=distance;viewport.scrollLeft=position;}else position=viewport.scrollLeft;frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);
 root.querySelectorAll('[data-carousel]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.carousel==='pause'){paused=!paused;update();}else{halt();const distance=group.getBoundingClientRect().width+24;if(button.dataset.carousel==='previous'&&viewport.scrollLeft<1)viewport.scrollLeft=distance;else if(viewport.scrollLeft>=distance)viewport.scrollLeft-=distance;viewport.scrollBy({left:(button.dataset.carousel==='next'?1:-1)*viewport.clientWidth*.75,behavior:motion.matches?'instant':'smooth'});}},opts));
 viewport.addEventListener('pointerenter',()=>{hover=true},opts);viewport.addEventListener('pointerleave',()=>{hover=false},opts);viewport.addEventListener('focusin',()=>{focused=true},opts);viewport.addEventListener('focusout',()=>{focused=false},opts);viewport.addEventListener('pointerdown',halt,opts);viewport.addEventListener('wheel',e=>{if(Math.abs(e.deltaX)>Math.abs(e.deltaY))halt();},{...opts,passive:true});viewport.addEventListener('keydown',halt,opts);
 const changed=()=>{if(motion.matches)halt();};motion.addEventListener('change',changed);
 const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;},{threshold:0});observer.observe(root);
 stopCarousel=()=>{cancelAnimationFrame(frame);controller.abort();observer.disconnect();motion.removeEventListener('change',changed);};
}
function home(){app.innerHTML=`<section class="campaign"><div class="campaign-copy"><span class="eyebrow">The texture collection</span><h1>Hair with <br>presence.</h1><p>Curls, waves and statement styles.<br>Find the texture you’ll make your own.</p><a class="btn btn-dark primary" href="#shop">Shop hair </a></div><div class="campaign-image"><img src="assets/wave-natural-v2.webp" width="1086" height="1448" alt="Model wearing long black body-wave hair in a softly lit ivory studio" fetchpriority="high"><div class="campaign-caption"><span>01 / The Soft Wave</span><a class="btn btn-light" href="#product/wave">View style</a></div></div></section><div class="collection-nav" aria-label="Shop by category"><a href="#shop" data-category="Wigs">Wigs <span>01</span></a><a href="#shop" data-category="Bundles">Bundles <span>02</span></a><a href="#shop" data-category="Haircare">Haircare <span>03</span></a><a class="btn btn-dark primary texture-cta" href="#guide">${icon('guide')}<span>Find your texture</span></a></div>${museCarousel()}<div class="wrap"><section class="section"><div class="section-head"><h2>The collection.</h2><a class="btn btn-outline-secondary text-link" href="#shop">Shop hair </a></div><div class="grid">${products.map(card).join('')}</div></section></div><div class="wrap"><section class="campaign-duo"><img src="assets/campaign-duo.webp" width="1536" height="1024" alt="Two models wearing body waves and deep curls, in plum and ivory blouses" loading="lazy"><div class="duo-caption"><div><span class="eyebrow">THE MANEMUSE CAMPAIGN</span><h2>Two textures.<br>One mood.</h2><p>Soft waves or defined curls. Find your signature, then see every angle in the gallery.</p><a class="btn btn-dark primary" href="#shop">Explore the collection</a></div></div></section></div><div class="wrap">${textureEdit()}<section class="section hair-notes"><div><h2>The hair edit.</h2><p>Choosing well. Caring better.</p><a href="#journal" class="btn btn-outline-secondary text-link">Read the journal </a></div><div class="journal-list">${articles.map((a,i)=>`<article><div><span class="eyebrow">${a.category}</span><h3>${a.title}</h3></div><a class="btn btn-outline-secondary" href="#article/${i}" aria-label="Read guide: ${a.title}">Read guide</a></article>`).join('')}</div></section></div>`}
function shop(){let list=products.filter(p=>(filter==='All'||p.cat===filter)&&(p.name+' '+p.texture+' '+p.cat).toLowerCase().includes(query.toLowerCase()));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);app.innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">THE COLLECTION</div><h1>The collection.</h1><p>Wigs, bundles and care essentials. Choose a style, then make it yours.</p></div><label class="field-label" for="catalogSearch">Search the collection</label><input class="searchbox" id="catalogSearch" type="search" placeholder="Search curls, waves, wigs…" value="${escapeHTML(query)}"><div class="filters">${['All','Wigs','Bundles','Haircare'].map(t=>`<button class="btn btn-outline-secondary chip ${t===filter?'active':''}" data-action="filter" data-value="${t}" aria-pressed="${t===filter}">${t}</button>`).join('')}<select id="sort" aria-label="Sort collection"><option value="featured">Featured</option><option value="low" ${sort==='low'?'selected':''}>Price: low to high</option><option value="high" ${sort==='high'?'selected':''}>Price: high to low</option></select></div><div class="grid section" style="padding-top:0">${list.length?list.map(card).join(''):'<p class="no-results">No matching styles. <button class="btn btn-outline-secondary text-link" data-action="clearFilters">Clear search and filters</button></p>'}</div></div>`}
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lengthsFor=p=>p.lengths||[16,18,20,22,24];
function validLength(p){const lengths=lengthsFor(p);return lengths.includes(selectedLength)?selectedLength:lengths[0]}
function unitPrice(p){return p.price+(p.cat==='Haircare'?0:(validLength(p)-lengthsFor(p)[0])*3500)}
function totalPrice(p){return Math.round(unitPrice(p)*bundleCount*(bundleCount===2?.9:bundleCount===3?.85:1))}
function pdp(id){const p=products.find(x=>x.id===id);if(!p){location.hash='shop';return}if(p.cat!=='Haircare')selectedLength=validLength(p);photoIndex=Math.max(0,Math.min(photoIndex,p.images.length-1));app.innerHTML=`<div class="wrap"><div class="breadcrumb"><a href="#shop">Collection</a> / ${p.cat} / ${p.name}</div><div class="pdp"><div><img class="pdp-photo" src="assets/${p.images[photoIndex]}" alt="${p.name} — ${photoLabel(p,photoIndex)}">${p.images.length>1?`<div class="thumbnails" aria-label="Product photos">${p.images.map((im,i)=>`<button data-action="photo" data-index="${i}" class="${photoIndex===i?'active':''}" aria-label="View photo ${i+1}: ${photoLabel(p,i)}" aria-pressed="${photoIndex===i}"><img src="assets/${im}" alt="" loading="lazy"></button>`).join('')}</div><div class="gallery-nav"><button class="btn btn-outline-secondary" data-action="photo" data-index="${photoIndex-1}" ${photoIndex===0?'disabled':''}>Previous photo</button><span class="gallery-count" role="status" aria-live="polite">${photoIndex+1} / ${p.images.length}</span><button class="btn btn-outline-secondary" data-action="photo" data-index="${photoIndex+1}" ${photoIndex===p.images.length-1?'disabled':''}>Next photo</button></div>`:''}<p class="gallery-label">${photoLabel(p,photoIndex)}</p></div><div class="pdp-info"><div class="eyebrow">${p.cat.toUpperCase()} / ${p.tag}</div><h1>${p.name}</h1><p>${p.desc}</p><div class="pdp-price">${money(unitPrice(p))}<small>${p.texture}</small></div><div class="qualities"><span>${icon('leaf')} Natural-looking finish</span><span>${icon('guide')} Your choice of fullness</span><span>${icon('shield')} Care guide included</span></div>${p.cat!=='Haircare'?`<div class="option-label"><span>CHOOSE YOUR LENGTH</span><span>${selectedLength} inches</span></div><div class="lengths">${lengthsFor(p).map(l=>`<button class="btn btn-outline-secondary ${l===selectedLength?'active':''}" data-action="length" data-value="${l}" aria-pressed="${l===selectedLength}">${l}″</button>`).join('')}</div>`:''}<div class="option-label"><span>${p.cat==='Bundles'?'BUILD YOUR BUNDLE':'CHOOSE YOUR SET'}</span><span>Set pricing</span></div><div class="bundles">${[1,2,3].map(n=>`<button class="bundle ${n===bundleCount?'active':''}" data-action="bundle" data-value="${n}" aria-pressed="${n===bundleCount}"><span class="radio"></span><span>${n} ${p.cat==='Bundles'?'bundle':'piece'}${n>1?'s':''}<small>${n===1?'Single piece':n===2?'Save 10% · Save on a second piece':'Save 15% · Best set price'}</small></span><b>${money(unitPrice(p)*n*(n===2?.9:n===3?.85:1))}</b></button>`).join('')}</div><button class="btn btn-dark primary full" data-action="add" data-id="${p.id}">${icon('shop')} Add to bag — ${money(totalPrice(p))}</button><p class="pdp-note">Illustrative product · Demo checkout</p><details open><summary>Product details</summary><p>${p.texture} · ${p.cat==='Haircare'?'Care set':selectedLength+' inches'}. Images represent the design concept. Confirm material, density and availability with the seller before a real purchase.</p></details><details><summary>Delivery & returns</summary><p>Demo policy: dispatch within 2–4 business days, with delivery quoted at checkout. Real delivery and return terms must be supplied by the store owner.</p></details><details><summary>Care for your hair</summary><p>Detangle gently from the ends, avoid excessive heat and follow the supplier’s washing instructions. <a class="btn btn-outline-secondary text-link" href="#article/0">Read the curl guide</a></p></details></div></div><section class="section"><div class="section-head"><h2>You might also love.</h2></div><div class="grid">${products.filter(x=>x.id!==id).slice(0,4).map(card).join('')}</div></section></div>`}
function savedPage(){app.innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">YOUR PERSONAL EDIT</div><h1>Saved styles.</h1><p>All the styles you have your eye on.</p></div>${saved.length?`<div class="grid section">${products.filter(p=>saved.includes(p.id)).map(card).join('')}</div>`:`<div class="empty">${icon('heart')}<h2>Nothing saved yet.</h2><p>Tap the heart on a style to save it here.</p><a class="btn btn-dark primary" href="#shop">Explore the collection</a></div>`}</div>`}
function bagPage(){const total=bag.reduce((a,x)=>a+x.price*x.qty,0);app.innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">ONE STEP CLOSER</div><h1>Your bag.</h1></div>${bag.length?`<div class="bag-layout"><div>${bag.map((x,i)=>{const p=products.find(p=>p.id===x.id);return `<div class="bag-row"><a href="#product/${p.id}"><img src="assets/${p.img}" alt="${p.name}"></a><div class="bag-details"><h3>${p.name}</h3><p>${p.cat==='Haircare'?'Care set':x.length+' inches'} · ${x.bundles} ${p.cat==='Bundles'?'bundle':'piece'}${x.bundles>1?'s':''}</p><div class="qty"><button data-action="qty" data-index="${i}" data-value="-1" aria-label="Reduce quantity">−</button><span>${x.qty}</span><button data-action="qty" data-index="${i}" data-value="1" aria-label="Increase quantity">+</button></div><button class="btn btn-outline-secondary remove" data-action="remove" data-index="${i}">Remove</button></div><div>${money(x.price*x.qty)}</div></div>`}).join('')}<a class="btn btn-outline-secondary back" href="#shop">Keep exploring</a></div><aside class="bag-summary"><h2 style="font-size:27px">Order summary</h2><div class="summary-line"><span>Subtotal</span><b>${money(total)}</b></div><div class="summary-line"><span>Delivery</span><span>Calculated at checkout</span></div><div class="summary-line" style="padding-top:20px"><span>Total before delivery</span><b>${money(total)}</b></div><button class="btn btn-dark primary full" data-action="checkout">Continue to checkout</button><p class="pdp-note">No payment will be collected.</p></aside></div>`:`<div class="empty">${icon('shop')}<h2>Your bag is empty.</h2><p>Explore the collection and add a style you love.</p><a class="btn btn-dark primary" href="#shop">Shop the collection </a></div>`}</div>`}
function guide(){const steps=[{title:'What feels most like you?',sub:'Start with the texture you naturally gravitate toward.',options:['Defined curls','Soft waves','Sleek & straight','Full-volume coils']},{title:'How will you wear it?',sub:'Make space for the moments that matter.',options:['Everyday ease','A special occasion','A fresh new look','A little of everything']},{title:'What length feels right?',sub:'The finishing touch to your signature.',options:['Shoulder-grazing · 16″','A little longer · 18″','Statement length · 22″','Long & luxurious · 24″']}];if(quizStep>=3){const p=products[quizAnswers[0]];selectedLength=[16,18,22,24][quizAnswers[2]];app.innerHTML=`<div class="guide-wrap"><div class="eyebrow">YOUR TEXTURE MATCH</div><h1>Hello, <em>${p.name.replace('The ','')}.</em></h1><p>${p.desc}</p><img style="width:240px;height:300px;object-fit:cover" src="assets/${p.img}" alt="${p.name}"><a class="btn btn-dark primary full" href="#product/${p.id}">Explore your match </a><button class="btn btn-outline-secondary text-link" style="margin:20px auto" data-action="restart">Find another muse</button></div>`;return}const s=steps[quizStep];app.innerHTML=`<div class="guide-wrap"><div class="eyebrow">THE TEXTURE FINDER</div><span class="eyebrow">${quizStep+1} / 3</span><h1>${s.title}</h1><p>${s.sub}</p><div class="quiz-options">${s.options.map((o,i)=>`<button class="btn btn-outline-secondary" data-action="quiz" data-value="${i}">${quizStep===0?`<img src="assets/${products[i].id}-detail.webp" alt="" loading="lazy">`:""}<span>${o}</span></button>`).join('')}</div>${quizStep?'<button class="btn btn-outline-secondary back" data-action="quizBack">Previous question</button>':''}</div>`}
function journal(){app.innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">THE JOURNAL</div><h1>The hair edit.</h1><p>Practical guides for choosing and caring for your hair.</p></div><div class="journal-grid section">${journalCards()}</div></div>`}
function article(i){const a=articles[i];if(!a){location.hash='journal';return}app.innerHTML=`<article class="article"><a class="btn btn-outline-secondary back" href="#journal">The hair edit</a><div class="eyebrow">${a.category}</div><h1>${a.title}</h1><p>${a.intro}</p><img src="assets/${a.img}" alt="${a.title}">${a.sections.map(s=>`<h2>${s[0]}</h2><p>${s[1]}</p>`).join('')}<a class="btn btn-dark primary" href="#shop">Find your signature </a></article>`}
function route(scroll=true){stopCarousel();cleanCart();const [rawPage='home',id]=location.hash.slice(1).split('/');const page=rawPage||'home';if(page==='shop')shop();else if(page==='product')pdp(id);else if(page==='saved')savedPage();else if(page==='bag')bagPage();else if(page==='checkout')checkoutPage();else if(page==='payment')paymentPage();else if(page==='payment-preview')paymentPreviewPage();else if(page==='guide')guide();else if(page==='journal')journal();else if(page==='article')article(id);else home();document.body.classList.toggle('checkout-page',['checkout','payment','payment-preview'].includes(page));document.title=['checkout','payment','payment-preview'].includes(page)?'Checkout | ManeMuse':'ManeMuse | Your hair. Your muse.';document.querySelector('.bottomnav').innerHTML=[['home','home','Home'],['shop','search','Explore'],['guide','guide','My texture'],['saved','heart','Saved'],['bag','shop','Bag']].map(([r,i,t])=>`<a href="#${r}" class="${page===r?'active':''}" ${page===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('');persist();startCarousel();if(scroll){window.scrollTo(0,0);if(['checkout','payment','payment-preview'].includes(page))app.focus({preventScroll:true})}}
function modal(html){document.querySelector('#modalContent').innerHTML=html;const heading=document.querySelector('#modalContent h2');if(heading){heading.id='dialogTitle';document.querySelector('#modal').setAttribute('aria-labelledby','dialogTitle')}document.querySelector('#modal').showModal()}
document.querySelector('.close').innerHTML=icon('close');document.querySelector('#menu').innerHTML=icon('menu');document.querySelector('#searchIcon').innerHTML=icon('search');document.querySelector('#savedIcon').innerHTML=icon('heart');document.querySelector('#bagIcon').innerHTML=icon('shop');
document.addEventListener('click',e=>{const category=e.target.closest('[data-category]');if(category){filter=category.dataset.category;query='';if(location.hash==='#shop')shop()}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,p=products.find(p=>p.id===b.dataset.id);if(a==='clearFilters'){query='';filter='All';shop()}else if(['shop','bag','saved'].includes(a))location.hash=a;else if(a==='product')location.hash='product/'+p.id;else if(a==='save'){saved=saved.includes(p.id)?saved.filter(x=>x!==p.id):[...saved,p.id];persist();route(false)}else if(a==='filter'){filter=b.dataset.value;shop()}else if(a==='length'){selectedLength=+b.dataset.value;pdp(location.hash.split('/')[1])}else if(a==='bundle'){bundleCount=+b.dataset.value;pdp(location.hash.split('/')[1])}else if(a==='photo'){photoIndex=+b.dataset.index;pdp(location.hash.split('/')[1]);document.querySelector('.thumbnails button.active')?.focus({preventScroll:true})}else if(a==='add'){const price=totalPrice(p),existing=bag.find(x=>x.id===p.id&&x.length===selectedLength&&x.bundles===bundleCount);if(existing)existing.qty++;else bag.push({id:p.id,length:selectedLength,bundles:bundleCount,price,qty:1});persist();toast('Added to bag.')}else if(a==='qty'){const i=+b.dataset.index;bag[i].qty+=+b.dataset.value;if(bag[i].qty<=0)bag.splice(i,1);persist();bagPage()}else if(a==='remove'){bag.splice(+b.dataset.index,1);persist();bagPage()}else if(a==='quiz'){quizAnswers[quizStep]=+b.dataset.value;quizStep++;guide();window.scrollTo(0,0)}else if(a==='quizBack'){quizStep--;guide()}else if(a==='restart'){quizStep=0;quizAnswers=[];guide()}else if(a==='close')document.querySelector('#modal').close();else if(a==='search'){location.hash='shop';setTimeout(()=>document.querySelector('#catalogSearch')?.focus(),30)}else if(a==='about'){modal(`<div class="eyebrow">ABOUT THIS CONCEPT</div><h2>Designed around your muse.</h2><p>ManeMuse is an original interactive storefront concept inspired by the supplied hair-commerce references. Its catalog, pricing and delivery policy are examples.</p><p>The campaign portraits and product visuals were generated specifically for ManeMuse. Layout inspiration comes from the supplied design references by Felitechy, Calypso, Oluyemi Samuel and Janeee.</p>`)}else if(a==='checkout'){location.hash='checkout'} });
document.addEventListener('input',e=>{if(e.target.id==='catalogSearch'){query=e.target.value;const pos=e.target.selectionStart;shop();const inp=document.querySelector('#catalogSearch');inp.focus();try{inp.setSelectionRange(pos,pos)}catch{}}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;shop()}});
window.addEventListener('hashchange',()=>{photoIndex=0;bundleCount=1;route()});document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});route();
